// Manual, read-only handoff. A green run or artifact name is never image evidence.
const repository = '2strongtrainers-art/Nicholas-AI-OS';
const workflowPath = '.github/workflows/deploy-argus-private-forensics.yml';
const workflowId = 418878767;
const base = 'https://github.com/' + repository;
const allowedFailures = new Set(['invalid_worker_origin', 'health_unverified', 'worker_not_configured',
  'github_key_missing', 'unauthorized_check_failed', 'authenticated_analysis_failed',
  'synthetic_integrity_failed', 'exiftool_unverified', 'exiftool_fixture_mismatch',
  'response_too_large', 'worker_request_failed', 'prerequisite_failed', 'unexpected_verification_error']);
const blockedFailures = new Set(['invalid_worker_origin', 'worker_not_configured', 'github_key_missing', 'prerequisite_failed']);
const expectedEvidence = {
  fixture_id: 'argus-synthetic-png-v1', source_bytes: 69,
  source_sha256: '5731a25f0c25c4e8b515f273b778da29ec74369400f93551a68507d5dacf77c3',
  unauthenticated_http: 401, authenticated_http: 200,
  exiftool: { FileType: 'PNG', MIMEType: 'image/png', ImageWidth: 1, ImageHeight: 1 },
  sensitive_metadata_included: false,
};
const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const exactKeys = (obj, keys) => isObject(obj) && Object.keys(obj).length === keys.length && keys.every(k => Object.hasOwn(obj, k));
const safeInteger = value => Number.isSafeInteger(value) && value > 0;
const validDate = value => typeof value === 'string' && /^\d{4}-\d\d-\d\dT/.test(value) && /(?:Z|[+-]\d\d:\d\d)$/.test(value) && Number.isFinite(Date.parse(value));
const sameEvidence = value => exactKeys(value, Object.keys(expectedEvidence)) &&
  Object.entries(expectedEvidence).every(([key, expected]) => key === 'exiftool'
    ? exactKeys(value.exiftool, Object.keys(expected)) && Object.entries(expected).every(([k, v]) => value.exiftool[k] === v)
    : value[key] === expected);
const now = new Date().toISOString();
const runPayload = $('Read ARGUS workflow runs').first().json;
const artifactPayload = $input.first().json;
const packet = $('Reviewed receipt (optional)').first().json.reviewed_artifact;
const executions = typeof $execution !== 'undefined' ? String($execution.id || '') : '';
const executionId = /^[A-Za-z0-9_-]{1,80}$/.test(executions) ? executions : null;

// Require the trusted GitHub endpoint's owner, workflow, event and branch metadata.
const runs = Array.isArray(runPayload.workflow_runs) ? runPayload.workflow_runs.filter(run =>
  isObject(run) && safeInteger(run.id) && safeInteger(run.run_attempt) &&
  run.workflow_id === workflowId && run.path === workflowPath && run.head_branch === 'main' &&
  ['workflow_dispatch', 'push'].includes(run.event) &&
  run.repository?.full_name === repository && run.head_repository?.full_name === repository &&
  /^[0-9a-f]{40}$/.test(run.head_sha || '') && validDate(run.created_at) && validDate(run.updated_at) &&
  Date.parse(run.created_at) <= Date.parse(run.updated_at) && Date.parse(run.updated_at) <= Date.now() + 60000
).sort((a, b) => Date.parse(b.created_at) - Date.parse(a.created_at) || b.id - a.id) : [];
const run = runs[0] || null;
let status = 'BLOCKED';
let reason = 'github_run_source_unavailable';
let verification = null;
let approvedArtifact = null;
let runReference = null;
let receiptKey = 'argus-source-unavailable';
if (run) {
  const version = run.id + '-' + run.run_attempt;
  const runUrl = base + '/actions/runs/' + run.id + '/attempts/' + run.run_attempt;
  receiptKey = 'argus-' + version;
  const conclusions = new Set(['success', 'failure', 'cancelled', 'timed_out', 'action_required', 'skipped', 'stale', 'neutral', 'startup_failure']);
  runReference = { run_id: String(run.id), run_attempt: run.run_attempt, head_sha: run.head_sha,
    run_url: runUrl, status: run.status === 'completed' ? 'completed' : 'not_completed',
    conclusion: conclusions.has(run.conclusion) ? run.conclusion : null };
  const artifactName = 'argus-verification-' + version;
  const artifacts = Array.isArray(artifactPayload.artifacts) ? artifactPayload.artifacts : [];
  const artifact = artifacts.find(item => isObject(item) && safeInteger(item.id) &&
    item.name === artifactName && item.expired === false &&
    item.workflow_run?.id === run.id && item.workflow_run?.head_sha === run.head_sha &&
    item.workflow_run?.head_branch === 'main' && /^sha256:[0-9a-f]{64}$/.test(item.digest || ''));
  if (run.status !== 'completed') {
    status = 'UNVERIFIED'; reason = 'run_not_completed';
  } else if (!conclusions.has(run.conclusion)) {
    reason = 'run_conclusion_unrecognized';
  } else if (packet == null) {
    status = run.conclusion === 'success' ? 'UNVERIFIED' : 'BLOCKED';
    reason = run.conclusion === 'success' ? 'sanitized_receipt_not_reviewed' : 'run_not_successful';
  } else if (!artifact) {
    reason = 'matching_artifact_unavailable';
  } else if (!exactKeys(packet, ['artifact_id', 'archive_sha256', 'receipt']) ||
      packet.artifact_id !== artifact.id || !/^[0-9a-f]{64}$/.test(packet.archive_sha256 || '') ||
      'sha256:' + packet.archive_sha256 !== artifact.digest) {
    reason = 'reviewed_artifact_provenance_mismatch';
  } else {
    const receipt = packet.receipt;
    const github = receipt?.github;
    const receiptValid = exactKeys(receipt, ['schema', 'service', 'scope', 'status', 'failure_code', 'observed_at', 'github', 'evidence']) &&
      receipt.schema === 'argus-verification-receipt-v1' && receipt.service === 'argus-prime-forensics' &&
      receipt.scope === 'synthetic_only' && validDate(receipt.observed_at) &&
      Date.parse(receipt.observed_at) >= Date.parse(run.created_at) &&
      Date.parse(receipt.observed_at) <= Date.parse(run.updated_at) + 60000 &&
      exactKeys(github, ['repository', 'workflow_path', 'run_id', 'run_attempt', 'head_sha', 'ref', 'event', 'run_url']) &&
      github.repository === repository && github.workflow_path === workflowPath &&
      github.run_id === String(run.id) && github.run_attempt === run.run_attempt &&
      github.head_sha === run.head_sha && github.ref === 'refs/heads/main' && github.event === run.event && github.run_url === runUrl;
    if (!receiptValid) {
      reason = 'sanitized_receipt_provenance_mismatch';
    } else if (receipt.status === 'ARGUS_SYNTHETIC_PASS' && receipt.failure_code === null && sameEvidence(receipt.evidence)) {
      if (run.conclusion !== 'success') {
        reason = 'run_receipt_conflict';
      } else {
        status = 'VERIFIED_SYNTHETIC'; reason = 'reviewed_synthetic_receipt_matches_github';
        verification = { status: receipt.status, failure_code: null, observed_at: receipt.observed_at, evidence: expectedEvidence };
      }
    } else if (['ARGUS_VERIFICATION_BLOCKED', 'ARGUS_VERIFICATION_FAILED'].includes(receipt.status) &&
        allowedFailures.has(receipt.failure_code) && receipt.evidence === null &&
        (receipt.status === 'ARGUS_VERIFICATION_BLOCKED') === blockedFailures.has(receipt.failure_code)) {
      if (run.conclusion === 'success') {
        reason = 'run_receipt_conflict';
      } else {
        status = receipt.status === 'ARGUS_VERIFICATION_BLOCKED' ? 'BLOCKED' : 'FAILED';
        reason = receipt.failure_code;
        verification = { status: receipt.status, failure_code: receipt.failure_code, observed_at: receipt.observed_at, evidence: null };
      }
    } else {
      reason = 'sanitized_receipt_invalid';
    }
    if (verification) approvedArtifact = { artifact_id: artifact.id, name: artifactName, archive_sha256: packet.archive_sha256,
      provenance: 'authenticated-reader-reviewed-artifact; digest-matched-to-public-GitHub-metadata' };
  }
}
const nextStep = status === 'VERIFIED_SYNTHETIC'
  ? 'Chief reviews this exact run and the n8n execution receipt; synthetic verification alone does not prove real-image cases or delivery acknowledgment.'
  : reason === 'worker_not_configured'
    ? 'Configure the independent encrypted ARGUS Worker secret and matching GitHub environment secret, rerun verify-existing, then review the new artifact.'
    : 'Review the linked GitHub run; supply its authenticated-download sanitized artifact with archive SHA-256, or fix the reported verification blocker and rerun.';
const item = { source: 'github', id: 'argus-verification',
  version: receiptKey + ':' + status + ':' + reason,
  title: 'ARGUS ' + status + ': ' + reason, next_step: nextStep,
  url: runReference?.run_url || base + '/actions/workflows/deploy-argus-private-forensics.yml',
  observed_at: now, due_at: null, direction: 'owner_action', priority: status === 'VERIFIED_SYNTHETIC' ? 'normal' : 'high' };
return [{ json: {
  schema: 'argus-chief-handoff-v1', status, reason, receipt_key: receiptKey,
  run: runReference, verification, reviewed_artifact: approvedArtifact,
  n8n_execution_id: executionId, chief_delivery: 'normalized_output_prepared; acknowledgment_not_observed',
  chief_snapshot: { run_id: (receiptKey + '-' + (executionId || 'manual')).slice(0, 80), as_of: now, coverage: { github: run ? 'ok' : 'partial' }, items: [item] },
  limitations: ['No secret or image uploads; public GitHub reads only.',
    'Reviewed artifact bytes and digest come from the authenticated reader; this workflow does not download or authenticate the archive itself.',
    'A green workflow without matching reviewed synthetic evidence is UNVERIFIED.',
    'No scheduled activation, data-table write, client contact, trade, or Chief receipt acknowledgment.'],
} }];
